#define GENERATE_UTIL_TYPES(type_base)                                  \
    typedef std::shared_ptr<const type_base##_t> type_base##_handle_t;  \
    typedef std::unordered_set<type_base##_handle_t,                    \
                               PtrHash<type_base##_t>,                     \
                               PtrEq<type_base##_t>> type_base##_set_t;    \
    template<class V>                                                   \
    using type_base##_map_t = std::unordered_map<type_base##_handle_t,V, \
                                                 PtrHash<type_base##_t>,   \
                                                 PtrEq<type_base##_t>>;

struct MockEnvironment {
    //----typedefs/classes----//
public:
   template<class T>
   struct PtrHash {
       size_t operator()(const std::shared_ptr<const T> & t) const {
           return std::hash<T>()(*t);
       }
   };
   template<class T>
   struct PtrEq {
       bool operator()(const std::shared_ptr<const T> & t1,
                       const std::shared_ptr<const T> & t2) const {
           return *t1==*t2;
       }
   };
    typedef int action_t;
    typedef int observation_t;
    typedef int state_t;
    GENERATE_UTIL_TYPES(action)
    GENERATE_UTIL_TYPES(observation)
    GENERATE_UTIL_TYPES(state)
    typedef double reward_t;
    //----methods----//
public:
    MockEnvironment(): state(new int(0)) {}
    virtual ~MockEnvironment(){}
    virtual void set_state(const state_handle_t & s) {state = s;}
    virtual state_handle_t get_state() const {return state;}
    virtual std::tuple<observation_handle_t,reward_t> transition(const action_handle_t & action_handle) {
        assert(*state==0 || *state==1);
        if(drand48()<0.1) {
            state = std::make_shared<state_t>(2);
        } else {
            if(*action_handle==0) {
                if(drand48()<0.1) state = std::make_shared<state_t>((*state+1)%2);
            } else {
                if(drand48()<0.9) state = std::make_shared<state_t>((*state+1)%2);
            }
        }
        return std::make_tuple<observation_handle_t,reward_t>(
            std::make_shared<const observation_t>(*state),
            reward_t(*state==1));
    }
    virtual action_set_t get_actions() {
        action_set_t actions;
        actions.insert(std::make_shared<action_t>(0));
        actions.insert(std::make_shared<action_t>(1));
        return actions;
    }
    virtual bool has_terminal_state() const {return true;}
    virtual bool is_terminal_state() const {return *state==2;}
    virtual bool has_max_reward() const {return true;}
    virtual reward_t max_reward() const {return 1;}
    virtual bool has_min_reward() const {return true;}

